// Запросы — те же, что делает UI (из бандла): решение — candidates.update({recruiting_status}).eq('id').select('id'),
// заметка — rpc add_internal_note{p_candidate_id,p_body,p_report_id}, чтение — rpc get_candidate_report (business: p_reason null).
import { Page, APIResponse } from '@playwright/test';
import { expect } from '../../fixtures';
import { Api } from '../support/api';

export const HIRING = {
  advanced_to_next_stage: 'הועבר לשלב הבא',
  further_clarification_needed: 'נדרש בירור נוסף',
  process_ended: 'התהליך הסתיים',
} as const;
export type HiringStatus = keyof typeof HIRING | 'pending_execution';
export const UNDECIDED = 'טרם נקבע';

export const TXT = {
  decisionFail: 'לא הצלחנו לשמור את ההחלטה, וההחלטה הקודמת נשמרה. בדקו את החיבור ונסו שוב.',
  noteFail: 'לא הצלחנו לשמור את ההערה, והטקסט שכתבתם נשאר כאן. בדקו את החיבור ונסו שוב.',
  notFound: 'המועמד לא נמצא',
  addNote: 'הוספת הערה',
};

type Person = { id?: string; full_name?: string } | string | null | undefined;
export type Hiring = { status: HiringStatus; changed_at: string | null; changed_by: Person };
export type Note = { id?: string; body: string; created_at?: string; created_by?: string; author?: Person };
export type Report = { hiring: Hiring | null; notes: Note[] | null; report: { id: string } | null; candidate?: { id: string; full_name: string } };

/** Совпадает ли автор/изменивший с пользователем (по id, если сервер его отдаёт; иначе — хотя бы имя заполнено). */
export function isPerson(p: Person, userId: string, fallbackId?: string) {
  if (!p) return false;
  if (typeof p === 'string') return p === userId;
  if (p.id) return p.id === userId;
  if (fallbackId) return fallbackId === userId;
  return !!p.full_name;
}

/** Кандидаты, видимые текущей сессии (тот же rpc, что и список /candidates). */
export async function listCandidates(api: Api): Promise<{ id: string; full_name: string }[]> {
  const res = await api.rpc('list_candidates');
  expect(res.status(), `list_candidates: ${await res.text()}`).toBe(200);
  return res.json();
}

export async function candidateId(api: Api, name: string): Promise<string> {
  const found = (await listCandidates(api)).filter((c) => c.full_name === name);
  expect(found, `кандидат «${name}» не найден в list_candidates`).toHaveLength(1);
  return found[0].id;
}

/** Отчёт кандидата так, как его читает экран business (p_reason null). */
export async function getReport(api: Api, id: string): Promise<Report> {
  const res = await api.rpc('get_candidate_report', { p_candidate_id: id, p_reason: null });
  expect(res.status(), `get_candidate_report: ${await res.text()}`).toBe(200);
  return res.json();
}

export const setDecision = (api: Api, id: string, status: HiringStatus): Promise<APIResponse> =>
  api.patch(`candidates?id=eq.${id}&select=id`, { recruiting_status: status });

export const addNote = (api: Api, id: string, body: string, reportId: string | null): Promise<APIResponse> =>
  api.rpc('add_internal_note', { p_candidate_id: id, p_body: body, p_report_id: reportId });

/** business: новый кандидат (link_only — ничего не отправляется), назначенный на managerId. */
export async function createCandidateAssigned(page: Page, name: string, managerId: string, simulation: string) {
  await page.goto('/candidates/new');
  const sim = page.locator('#candidate-simulation_id');
  await expect(sim).toBeVisible();
  const opts = await sim.locator('option').evaluateAll((o) => (o as HTMLOptionElement[]).map((x) => ({ v: x.value, t: x.textContent || '' })));
  const target = opts.filter((o) => o.v && o.t.includes(simulation));
  expect(target, `нет активной симуляции «${simulation}» (QA_CALL_SIMULATION)`).toHaveLength(1);
  const managers = await page.locator('#candidate-assigned_manager_id option').evaluateAll((o) =>
    (o as HTMLOptionElement[]).map((x) => x.value).filter(Boolean),
  );
  expect(managers, `рекрутёра ${managerId} нет в списке «מנהל אחראי»`).toContain(managerId);
  await page.locator('#candidate-full_name').fill(name);
  await page.locator('#candidate-phone').fill('05000094' + String(10 + Math.floor(Math.random() * 90)));
  await page.locator('#candidate-role_title').fill('QA-AUTO נציג');
  await page.locator('#candidate-assigned_manager_id').selectOption(managerId);
  await sim.selectOption(target[0].v);
  await page.locator('input[name=send_channel][value=link_only]').check();
  const created = page.waitForResponse((r) => r.url().includes('/rpc/create_candidate'));
  await page.getByRole('button', { name: /יצירת קישור/ }).click();
  expect((await created).status(), 'create_candidate').toBe(200);
}

/** Ячейка «החלטת גיוס» строки кандидата в /candidates (поиск ?q=, при необходимости — фильтр ?status=). */
export async function decisionCellFor(page: Page, name: string, status?: string) {
  const qs = new URLSearchParams({ ...(status ? { status } : {}), q: name });
  await page.goto(`/candidates?${qs}`);
  const row = page.getByTestId('candidate-row').filter({ has: page.locator('td[data-label="שם"]').getByText(name, { exact: true }) });
  await expect(row, `строка «${name}» в /candidates?${qs}`).toHaveCount(1);
  return { row, cell: row.locator('td[data-label="החלטת גיוס"]') };
}
